{
  "name": "opencode-model-tiers",
  "version": "0.1.10",
  "description": "OpenCode plugin for resolving named model tiers in project and global config.",
  "type": "module",
  "main": "./index.js",
  "bin": {
    "opencode-model-tiers": "cli.js"
  },
  "dependencies": {
    "@inquirer/prompts": "^7.10.1"
  },
  "exports": {
    ".": "./index.js",
    "./server": "./index.js"
  },
  "files": [
    "index.js",
    "cli.js",
    "lib",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "check": "node --check index.js && node --check cli.js",
    "test": "node --test",
    "pack:check": "npm pack --dry-run --json"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "model",
    "configuration"
  ],
  "author": "dartyuhov",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/dartyuhov/opencode-model-tiers.git"
  },
  "bugs": {
    "url": "https://github.com/dartyuhov/opencode-model-tiers/issues"
  },
  "homepage": "https://github.com/dartyuhov/opencode-model-tiers#readme",
  "publishConfig": {
    "access": "public"
  }
}
